/**
 * Web only: registers the offline service worker generated by scripts/build-sw.ts.
 * Production builds only. Never reloads the page: a new build is picked up on the next launch,
 * which avoids mixing old and new assets within one session.
 */
export function registerServiceWorker(): void {
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return;
  if (process.env.NODE_ENV !== 'production') return;
  const base = process.env.EXPO_BASE_URL ?? '';
  const register = () => {
    navigator.serviceWorker.register(`${base}/sw.js`, { scope: `${base}/` }).catch((error) => {
      console.warn('Service worker registration failed', error);
    });
  };
  if (document.readyState === 'complete') register();
  else window.addEventListener('load', register, { once: true });
}
